package com.restaurant.pos.catalog;
import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api/catalog") public class CatalogController { private final CatalogRepository products; private final CategoryRepository categories; CatalogController(CatalogRepository p,CategoryRepository c){products=p;categories=c;}
 record ProductRequest(@NotBlank String name,String description,@NotNull @DecimalMin("0") BigDecimal price,@NotNull Long categoryId,boolean available){} record ProductView(Long id,String name,String description,BigDecimal price,boolean available,String category){ static ProductView of(Product p){return new ProductView(p.id,p.name,p.description,p.price,p.available,p.category.code);} }
 @GetMapping public List<ProductView> list(){return products.findAll().stream().map(ProductView::of).toList();} @GetMapping("/available") public List<ProductView> available(){return products.findByAvailableTrueOrderByName().stream().map(ProductView::of).toList();}
 @PostMapping @PreAuthorize("hasRole('ADMIN')") ProductView create(@Valid @RequestBody ProductRequest r){return ProductView.of(save(new Product(),r));} @PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") ProductView update(@PathVariable Long id,@Valid @RequestBody ProductRequest r){return ProductView.of(save(products.findById(id).orElseThrow(()->new IllegalArgumentException("Product not found")),r));}
 private Product save(Product p,ProductRequest r){p.name=r.name;p.description=r.description;p.price=r.price;p.available=r.available;p.category=categories.findById(r.categoryId).orElseThrow(()->new IllegalArgumentException("Category not found"));return products.save(p);} @GetMapping("/categories") public List<Category> cats(){return categories.findAll();}
}
